+import { type ReactElement, useId } from "react";
+import type { ValueOf } from "@/types/ValueOf";
+
+/** カードの配色の種類。 */
+export const ActionCardTones = {
+  /**
+   * 並んだカードのうち、いちばん勧めたい操作の配色（青系）。
+   *
+   * UI 案の `#4db2ff` 地に白文字は約 2.3:1 で 4.5:1 に届かないので、UI 案の青の組み合わせから離れた。
+   * この配色は開始画面（#1062）で決めたもので、UI 案に裏付けのある汎用の配色ではない。
+   * hover 中の `#0a74c9` on `#e7f1fa` も約 4.2:1 で届かないが、押す直前の一時的な状態として受け入れている。
+   */
+  Primary: "Primary",
+  /** 勧め分けをしない操作の配色（灰系）。 */
+  Normal: "Normal",
+} as const;
+
+/** カードの配色。 */
+export type ActionCardTone = ValueOf<typeof ActionCardTones>;
+
+/** カード 1 枚の中身。綴り・アイコン・配色の種類を持つ。 */
+export type ActionCardFace = Readonly<{
+  /** カードの名前になる見出し。 */
+  title: string;
+  /** 押すと何が起きるかの 1 行。 */
+  description: string;
+  /** 同じ操作を呼ぶキーボードの割り当ての表記。 */
+  shortcut: string;
+  /** アイコン（viewBox 0 0 24 24）を描く path の `d`。 */
+  iconPaths: readonly string[];
+  /** 配色の種類。 */
